{
  "root": "catan_main_stack",
  "state": {},
  "elements": {
    "catan_main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "overview_section",
        "setup_section",
        "victory_section",
        "strategies_section",
        "actions_section"
      ]
    },
    "overview_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_header_stack",
        "overview_text"
      ]
    },
    "overview_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "overview_icon",
        "overview_title"
      ]
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000339_01_1_dice-5.svg"
      },
      "children": []
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Catan Game Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "Catan (formerly \"Settlers of Catan\") is a popular board game where players compete to build the largest civilization on the fictional island of Catan. The core objective is to be the first player to reach 10 Victory Points (VPs) by strategically settling, building, and trading resources."
      },
      "children": []
    },
    "setup_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "setup_header_stack",
        "setup_intro_text",
        "setup_list_stack"
      ]
    },
    "setup_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "setup_icon",
        "setup_title"
      ]
    },
    "setup_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000339_01_2_hexagon.svg"
      },
      "children": []
    },
    "setup_title": {
      "type": "Text",
      "props": {
        "text": "Game Setup and Core Gameplay",
        "variant": "h2"
      },
      "children": []
    },
    "setup_intro_text": {
      "type": "Text",
      "props": {
        "text": "The game board is made up of hexagonal tiles representing different terrain types (forest, hills, pastures, fields, mountains) that produce resources (wood, brick, wool, grain, ore). Each tile has a number token, and when that number is rolled on two dice, the adjacent settlements and cities produce the corresponding resource."
      },
      "children": []
    },
    "setup_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "setup_list_item_1",
        "setup_list_item_2",
        "setup_list_item_3",
        "setup_list_item_4",
        "setup_list_item_5",
        "setup_list_item_6"
      ]
    },
    "setup_list_item_1": {
      "type": "Text",
      "props": {
        "text": "Resource Production: On your turn, you roll two dice. The sum determines which hexes produce resources. Players with settlements or cities adjacent to these hexes collect the resources."
      },
      "children": []
    },
    "setup_list_item_2": {
      "type": "Text",
      "props": {
        "text": "Actions: After collecting resources, you can perform actions:"
      },
      "children": []
    },
    "setup_list_item_3": {
      "type": "Text",
      "props": {
        "text": "Building: Spend resources to build roads, settlements, and cities."
      },
      "children": []
    },
    "setup_list_item_4": {
      "type": "Text",
      "props": {
        "text": "Trading: Trade resources with other players, or with the bank (at a less favorable rate)."
      },
      "children": []
    },
    "setup_list_item_5": {
      "type": "Text",
      "props": {
        "text": "Development Cards: Purchase special cards that can grant VPs, knight cards (to move the Robber), or progress cards."
      },
      "children": []
    },
    "setup_list_item_6": {
      "type": "Text",
      "props": {
        "text": "The Robber: If a 7 is rolled, no resources are produced. Instead, the player who rolled the 7 moves the Robber to any hex, blocking its production, and steals a resource card from a player adjacent to that hex. If you have more than 7 resource cards when a 7 is rolled, you must discard half of them."
      },
      "children": []
    },
    "victory_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "victory_header_stack",
        "victory_intro_text",
        "victory_list_stack"
      ]
    },
    "victory_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "victory_icon",
        "victory_title"
      ]
    },
    "victory_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000339_01_3_trophy.svg"
      },
      "children": []
    },
    "victory_title": {
      "type": "Text",
      "props": {
        "text": "Achieving Victory in Catan",
        "variant": "h2"
      },
      "children": []
    },
    "victory_intro_text": {
      "type": "Text",
      "props": {
        "text": "To win, you must be the first player to accumulate 10 Victory Points (VPs). Here's how VPs are typically earned:"
      },
      "children": []
    },
    "victory_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "victory_list_item_1",
        "victory_list_item_2",
        "victory_list_item_3",
        "victory_list_item_4",
        "victory_list_item_5"
      ]
    },
    "victory_list_item_1": {
      "type": "Text",
      "props": {
        "text": "Settlements: Each settlement is worth 1 VP."
      },
      "children": []
    },
    "victory_list_item_2": {
      "type": "Text",
      "props": {
        "text": "Cities: Upgrade a settlement to a city for 2 VPs."
      },
      "children": []
    },
    "victory_list_item_3": {
      "type": "Text",
      "props": {
        "text": "Longest Road: The first player to build a continuous road of at least 5 segments, and longer than any other player's road, earns 2 VPs."
      },
      "children": []
    },
    "victory_list_item_4": {
      "type": "Text",
      "props": {
        "text": "Largest Army: The first player to play 3 \"Knight\" development cards, and have more knights than any other player, earns 2 VPs."
      },
      "children": []
    },
    "victory_list_item_5": {
      "type": "Text",
      "props": {
        "text": "Development Cards: Some development cards grant immediate VPs when revealed."
      },
      "children": []
    },
    "strategies_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "strategies_header_stack",
        "strategies_list_stack"
      ]
    },
    "strategies_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategies_icon",
        "strategies_title"
      ]
    },
    "strategies_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000339_01_4_lightbulb.svg"
      },
      "children": []
    },
    "strategies_title": {
      "type": "Text",
      "props": {
        "text": "Key Strategies for Success",
        "variant": "h2"
      },
      "children": []
    },
    "strategies_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_list_item_1",
        "strategy_list_item_2",
        "strategy_list_item_3",
        "strategy_list_item_4",
        "strategy_list_item_5",
        "strategy_list_item_6"
      ]
    },
    "strategy_list_item_1": {
      "type": "Text",
      "props": {
        "text": "Optimal Placement: Your starting settlements are crucial. Aim for hexes with high-probability numbers (6s and 8s) that produce a variety of resources. Connecting to a port can also be very beneficial for specific trading."
      },
      "children": []
    },
    "strategy_list_item_2": {
      "type": "Text",
      "props": {
        "text": "Resource Diversification: Try to get access to all five resources (wood, brick, wool, grain, ore) to avoid being completely reliant on trades."
      },
      "children": []
    },
    "strategy_list_item_3": {
      "type": "Text",
      "props": {
        "text": "Early Road Building: Roads are cheap and allow you to expand, claim new settlement spots, and potentially earn the Longest Road bonus."
      },
      "children": []
    },
    "strategy_list_item_4": {
      "type": "Text",
      "props": {
        "text": "Strategic Trading: Don't be afraid to trade! Negotiate with other players to get the resources you need, even if it means giving them something useful. Avoid making one player too powerful."
      },
      "children": []
    },
    "strategy_list_item_5": {
      "type": "Text",
      "props": {
        "text": "Development Cards: Don't underestimate development cards. Knights can protect you from the Robber or steal resources, while VPs can be a surprise win condition."
      },
      "children": []
    },
    "strategy_list_item_6": {
      "type": "Text",
      "props": {
        "text": "Robber Management: Use the Robber strategically to block opponents' key resource production, especially if they are close to winning or have a monopoly on a resource you need."
      },
      "children": []
    },
    "actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "actions_header_stack",
        "actions_button_stack"
      ]
    },
    "actions_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "actions_icon",
        "actions_title"
      ]
    },
    "actions_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000339_01_5_play.svg"
      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Ready to Play?",
        "variant": "h2"
      },
      "children": []
    },
    "actions_button_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "center"
      },
      "children": [
        "learn_more_button",
        "buy_now_button"
      ]
    },
    "learn_more_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.catan.com/game/catan"
          }
        }
      }
    },
    "buy_now_button": {
      "type": "Button",
      "props": {
        "label": "Buy Now",
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.amazon.com/Catan-Board-Game-Family-Strategy/dp/B000W7JWUE"
          }
        }
      }
    }
  }
}
